import{_ as t,o as r,c as s,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Service Status","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/service-status.md","filePath":"user-guide/settings/service-status.md","lastUpdated":1785993908000}'),n={name:"user-guide/settings/service-status.md"};function a(i,e,l,c,h,d){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="service-status" tabindex="-1">Service Status <a class="header-anchor" href="#service-status" aria-label="Permalink to &quot;Service Status&quot;">​</a></h1><p>Manages the background indexing service, and gives you a live view of its logs.</p><h2 id="service-control" tabindex="-1">Service control <a class="header-anchor" href="#service-control" aria-label="Permalink to &quot;Service control&quot;">​</a></h2><p>A status card shows the elevated indexer&#39;s current state — <strong>Installing</strong>, <strong>Indexing</strong>, <strong>Ready</strong> (with a live file/folder count), or <strong>Error</strong> — with a matching icon (spinner, checkmark, or error badge).</p><p>An <strong>Install &amp; Start Service</strong> button appears only when the service isn&#39;t installed yet or hit an error; once it&#39;s installed and running there&#39;s no manual start/stop/uninstall control on this page — the service is expected to just keep running in the background.</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>Three tabs — <strong>App</strong>, <strong>Hook</strong>, <strong>Service</strong> — corresponding to the three processes Lertaro runs (the elevated background indexer, the per-user App you interact with, and the keyboard-hook process). Each tab shows that process&#39;s log lines, color-coded by level.</p><ul><li><strong>Level filter</strong> dropdown — All / Error / Warn / Info / Debug.</li><li><strong>Search box</strong> — filters the visible lines by keyword, combined with the level filter.</li><li><strong>Clear</strong> button — empties the log for the currently selected tab. Clearing the Service tab&#39;s log is routed through the service itself (the App process doesn&#39;t have permission to write to it directly); the App and Hook logs are cleared directly since they&#39;re per-user files.</li></ul><p>This is the first place to look when troubleshooting — see <a href="./../troubleshooting.html#still-stuck">Troubleshooting</a>.</p>',9)])])}const p=t(n,[["render",a]]);export{u as __pageData,p as default};
